function harvest(cells){if(busy)return;captureUndo();hintPath=[];busy=true;moves--;cascadeCount=0;recordMissionEvent("chain",cells.length);recordMissionEvent("harvest",1);recordObjectiveEvent("chain",cells.length);recordObjectiveEvent("harvest",1);if(cells.length>=4){recordMissionEvent("special",1);recordObjectiveEvent("special",1)}gameStats.harvests++;gameStats.longestChain=Math.max(gameStats.longestChain,cells.length);saveStats();saveLevelBest();awardAchievement("first-harvest");if(cells.length>=5)awardAchievement("long-chain");if(cells.length>=10)awardAchievement("master-chain");const crop=G.cropAt(board,cells[0]),special=G.specialClearCells(board,cells),seedBurst=cells.length===4,storm=cells.length>=7,removed=special.length?special:cells.map(x=>({r:x.r,c:x.c})),base=G.scoreForChain(cells.length),bonus=special.length?special.length*(seedBurst?5:10):0;if(seedBurst)awardAchievement("seed-burst");if(storm)awardAchievement("harvest-storm");else if(special.length&&!seedBurst)awardAchievement("golden-harvest");score+=base+bonus;gameStats.totalPoints+=base+bonus;saveStats();saveProgress();saveLevelBest();playEffect(storm?"storm":special.length?"golden":"harvest");if(vibrationOn&&navigator.vibrate)try{navigator.vibrate(storm?[35,25,55]:special.length?35:15)}catch(_){}updateStats();if(storm)announce("HARVEST STORM! A full row and column cleared! +"+(base+bonus)+" points.","success");else if(seedBurst)announce("SEED BURST! Cleared nearby crops for +"+(base+bonus)+" points.","success");else if(special.length)announce("GOLDEN HARVEST! Every "+G.CROPS[crop].name.toLowerCase()+" crop cleared! +"+(base+bonus)+" points.","success");else announce("Harvested "+cells.length+" crops! +"+base+" points."+(cells.length>=4?" Long-chain bonus!":""),"success");clearCells(removed,seedBurst?200:170)}
function showLevelComplete(objective,scoreGoal){const dialog=$("level-complete-dialog");if(!dialog)return;if($("level-complete-description"))$("level-complete-description").textContent=objective.title+" complete! "+objective.description;if($("level-complete-score"))$("level-complete-score").textContent=score.toLocaleString();if($("level-complete-stars"))$("level-complete-stars").textContent="★".repeat(Math.max(1,G.starsForScore(score,scoreGoal)))+"☆".repeat(3-Math.max(1,G.starsForScore(score,scoreGoal)));if(typeof dialog.showModal==="function"&&!dialog.open)dialog.showModal();else dialog.setAttribute("open","")}
