function evaluateState(){const scoreGoal=dailyMode?dailyChallenge.goal:G.goalForLevel(level),objective=G.objectiveForLevel(level),won=dailyMode?score>=scoreGoal:objectiveState.complete;if(won){completed=true;saveProgress();saveLevelBest();if(!dailyMode){levelStars=G.recordLevelStars(levelStars,level,Math.max(1,G.starsForScore(score,scoreGoal)));saveLevelStars()}if(dailyMode){try{localStorage.setItem("maize-crush-daily-complete",dailyChallenge.date);const history=G.recordDailyCompletion(readDailyHistory(),dailyChallenge.date);localStorage.setItem("maize-crush-daily-history",JSON.stringify(history));const streak=G.dailyStreakForDates(history,todayKey());if(streak>=7)awardAchievement("daily-streak");announce("DAILY CHALLENGE COMPLETE! You reached "+scoreGoal+" points. Daily streak: "+streak+" day"+(streak===1?"":"s")+"!","success")}catch(_){announce("DAILY CHALLENGE COMPLETE! You reached "+scoreGoal+" points.","success")}awardAchievement("daily-champion")}else{gameStats.levelsCompleted++;saveStats();awardAchievement("level-up");announce("LEVEL COMPLETE! "+objective.title+" achieved. Ready for the next field?","success");showLevelComplete(objective,scoreGoal)}}else if(moves<=0){completed=true;announce(dailyMode?"Daily challenge over. Try again or return to the main harvest.":"Moves used up. Try again and complete: "+objective.title+".","warning");showLevelFailed(objective,scoreGoal)}else if(!lastMessage.startsWith("Harvested")&&!lastMessage.startsWith("GOLDEN")&&!lastMessage.startsWith("Cascade"))announce("Keep going — "+(dailyMode?"reach the daily score target.":objective.description));updateStats();saveRoundCheckpoint()}
