function showStatistics(){const dialog=$("statistics-dialog"),body=$("statistics-body");if(!dialog||!body)return;const rows=[["Rounds started",gameStats.gamesPlayed],["Successful harvests",gameStats.harvests],["Crops cleared",gameStats.cropsCleared],["Lifetime points",gameStats.totalPoints.toLocaleString()],["Longest chain",gameStats.longestChain],["Levels completed",gameStats.levelsCompleted],["Level stars earned",G.totalLevelStars(levelStars)+" / "+(Object.keys(levelStars).length*3)],["Boosters used",gameStats.boostersUsed],["Cascades triggered",gameStats.cascades],["Daily challenge streak",G.dailyStreakForDates(readDailyHistory(),todayKey())+" days"]];body.innerHTML="";rows.forEach(([label,value])=>{const row=document.createElement("div");row.className="statistics-row";const name=document.createElement("span"),amount=document.createElement("strong");name.textContent=label;amount.textContent=String(value);row.append(name,amount);body.append(row)});if(dialog.showModal)dialog.showModal();else dialog.setAttribute("open","")}
function showFarmJournal(){const dialog=$("farm-journal-dialog"),body=$("farm-journal-body"),total=$("farm-journal-total");if(!dialog||!body)return;body.innerHTML="";if(total)total.textContent=G.totalJournalCrops(cropJournal).toLocaleString();G.CROPS.forEach(crop=>{const count=cropJournal[crop.id]||0,milestones=[100,500,1000],earned=milestones.filter(n=>count>=n).length,next=milestones.find(n=>count<n);const row=document.createElement("article");row.className="journal-crop";const icon=document.createElement("span");icon.className="journal-icon";icon.textContent=crop.emoji;const copy=document.createElement("div"),name=document.createElement("strong"),detail=document.createElement("p"),track=document.createElement("div"),fill=document.createElement("div"),meta=document.createElement("span");copy.className="journal-copy";name.textContent=crop.name;detail.textContent=next?count.toLocaleString()+" harvested · next milestone "+next.toLocaleString():count.toLocaleString()+" harvested · all milestones earned";track.className="journal-track";fill.className="journal-fill";fill.style.width=Math.min(100,count/Math.max(1,next||1000)*100)+"%";track.append(fill);meta.className="journal-badge";meta.textContent=earned+" / 3 milestones";copy.append(name,detail,track);row.append(icon,copy,meta);body.append(row)});if(dialog.showModal)dialog.showModal();else dialog.setAttribute("open","")}
